```python
import json
import logging
from pathlib import Path
from typing import Any, Optional, Union

logger = logging.getLogger(__name__)


class JSONFileError(Exception):
    """Raised when a JSON file cannot be read or parsed."""


def read_json_file(
    path: Union[str, Path],
    default: Optional[Any] = None,
    raise_on_error: bool = False,
    encoding: str = "utf-8",
) -> Any:
    """
    Read a JSON file from disk and return the parsed object.

    Args:
        path: Path to the JSON file.
        default: Value returned if an error occurs (when raise_on_error is False).
        raise_on_error: If True, raise JSONFileError instead of returning `default`.
        encoding: File encoding (default: utf-8).

    Returns:
        The parsed JSON object (dict, list, str, int, float, bool, or None),
        or `default` if an error occurred and raise_on_error is False.

    Raises:
        JSONFileError: If raise_on_error is True and the file can't be read/parsed.
    """
    file_path = Path(path)

    def _fail(message: str, exc: Exception) -> Any:
        if raise_on_error:
            raise JSONFileError(message) from exc
        logger.error(message)
        return default

    try:
        with file_path.open("r", encoding=encoding) as f:
            return json.load(f)

    except FileNotFoundError as e:
        return _fail(f"File not found: {file_path}", e)

    except IsADirectoryError as e:
        return _fail(f"Expected a file but found a directory: {file_path}", e)

    except PermissionError as e:
        return _fail(f"Permission denied when reading: {file_path}", e)

    except UnicodeDecodeError as e:
        return _fail(
            f"Could not decode {file_path} using encoding '{encoding}': {e}", e
        )

    except json.JSONDecodeError as e:
        return _fail(
            f"Invalid JSON in {file_path} at line {e.lineno}, "
            f"column {e.colno}: {e.msg}",
            e,
        )

    except OSError as e:
        # Catches other I/O issues (e.g., device errors, too many open files)
        return _fail(f"OS error while reading {file_path}: {e}", e)
```

## Usage Examples

```python
logging.basicConfig(level=logging.INFO)

# 1. Basic usage – returns None on failure
config = read_json_file("config.json")

# 2. Provide a fallback default
settings = read_json_file("settings.json", default={})

# 3. Raise an exception instead of returning a default
try:
    data = read_json_file("data.json", raise_on_error=True)
except JSONFileError as e:
    print(f"Failed to load data: {e}")
    # Original exception is available via e.__cause__
```

## Design Notes

- **Specific exceptions first**: `FileNotFoundError`, `IsADirectoryError`, and `PermissionError` are all subclasses of `OSError`, so they're caught before the generic `OSError` handler to give precise messages.
- **Helpful parse errors**: `JSONDecodeError` exposes `lineno` and `colno`, which makes malformed files much easier to debug.
- **Two error modes**: Return a `default` for convenience, or set `raise_on_error=True` when the caller needs to handle failures explicitly. Raising preserves the original exception via `from exc`.
- **Mutable default safety**: Passing `default={}` is fine here because it's a call-time argument, not a function-definition default.
- **Logging over printing**: Uses `logging` so callers control verbosity and output destination.
- **`pathlib.Path`**: Accepts both strings and `Path` objects.

