```python
import json
import logging
from pathlib import Path
from typing import Any, Optional, Union

logger = logging.getLogger(__name__)


class JSONReadError(Exception):
    """Raised when a JSON file cannot be read or parsed."""
    pass


def read_json_file(
    file_path: Union[str, Path],
    default: Optional[Any] = None,
    raise_on_error: bool = False,
    encoding: str = "utf-8",
) -> Any:
    """
    Read a JSON file from disk and return the parsed object.

    Args:
        file_path: Path to the JSON file.
        default: Value to return if an error occurs (when raise_on_error is False).
        raise_on_error: If True, raise JSONReadError instead of returning `default`.
        encoding: File encoding (defaults to UTF-8).

    Returns:
        The parsed JSON object (dict, list, str, int, float, bool, or None),
        or `default` if an error occurred and raise_on_error is False.

    Raises:
        JSONReadError: If raise_on_error is True and the file can't be read/parsed.
    """
    path = Path(file_path)

    def handle_error(message: str, exc: Exception) -> Any:
        logger.error(message)
        if raise_on_error:
            raise JSONReadError(message) from exc
        return default

    try:
        with path.open("r", encoding=encoding) as f:
            return json.load(f)

    except FileNotFoundError as e:
        return handle_error(f"File not found: {path}", e)

    except IsADirectoryError as e:
        return handle_error(f"Expected a file but found a directory: {path}", e)

    except PermissionError as e:
        return handle_error(f"Permission denied when reading: {path}", e)

    except UnicodeDecodeError as e:
        return handle_error(
            f"Could not decode {path} using encoding '{encoding}': {e}", e
        )

    except json.JSONDecodeError as e:
        return handle_error(
            f"Invalid JSON in {path} at line {e.lineno}, column {e.colno}: {e.msg}", e
        )

    except OSError as e:
        # Catch-all for other I/O problems (e.g., disk errors)
        return handle_error(f"OS error while reading {path}: {e}", e)
```

### Example usage

```python
logging.basicConfig(level=logging.INFO)

# 1. Return a fallback value on failure
config = read_json_file("config.json", default={})
print(config)

# 2. Raise a single, well-defined exception type on failure
try:
    data = read_json_file("data.json", raise_on_error=True)
except JSONReadError as e:
    print(f"Failed to load data: {e}")
```

### Design notes

- **Specific exceptions first:** Each failure mode (missing file, permissions, bad encoding, malformed JSON) gets a descriptive message, which makes debugging much easier than a generic "something went wrong."
- **`OSError` as a catch-all:** `FileNotFoundError`, `PermissionError`, and `IsADirectoryError` are all subclasses of `OSError`, so they're listed first; the final `OSError` handler catches any remaining I/O issues.
- **Flexible error strategy:** Callers choose between a silent fallback (`default`) or an exception (`raise_on_error=True`). The custom `JSONReadError` lets callers catch one exception type while preserving the original cause via `from exc`.
- **Distinguishing failure from valid `null`:** A JSON file containing `null` legitimately parses to `None`. If you need to tell that apart from a failure, use `raise_on_error=True` or pass a unique sentinel as `default`.
- **Logging instead of printing:** Uses the `logging` module so the application controls how errors are reported.
- **Explicit encoding:** Defaults to UTF-8 (the JSON standard) rather than relying on the platform default, which varies across systems.

