# Reading a JSON File with Error Handling

```python
import json
import os


def read_json_file(file_path):
    """
    Read and parse a JSON file, returning the parsed object.

    Args:
        file_path (str): Path to the JSON file.

    Returns:
        Parsed JSON object (dict, list, etc.), or None if an error occurred.
    """
    # Check if the file exists
    if not os.path.exists(file_path):
        print(f"Error: File not found: {file_path}")
        return None

    try:
        with open(file_path, "r", encoding="utf-8") as f:
            return json.load(f)

    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON in {file_path}: {e}")
    except PermissionError:
        print(f"Error: Permission denied: {file_path}")
    except OSError as e:
        print(f"Error reading file {file_path}: {e}")
    except UnicodeDecodeError:
        print(f"Error: File is not valid UTF-8 text: {file_path}")

    return None
```

## Example Usage

```python
data = read_json_file("config.json")

if data is not None:
    print("Loaded:", data)
else:
    print("Failed to load JSON file.")
```

## Alternative: Raising Exceptions Instead

If you'd rather have the caller decide how to handle errors (often better for libraries), you can raise a custom exception:

```python
class JSONFileError(Exception):
    pass


def read_json_file_strict(file_path):
    try:
        with open(file_path, "r", encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        raise JSONFileError(f"File not found: {file_path}")
    except json.JSONDecodeError as e:
        raise JSONFileError(f"Invalid JSON in {file_path}: {e}")
    except OSError as e:
        raise JSONFileError(f"Could not read {file_path}: {e}")


# Usage
try:
    data = read_json_file_strict("config.json")
except JSONFileError as e:
    print(f"Failed: {e}")
```

**Key points:**
- `json.JSONDecodeError` catches malformed JSON (it's a subclass of `ValueError`)
- `encoding="utf-8"` avoids platform-dependent encoding issues
- The first version returns `None` on failure (simple); the second raises exceptions (more flexible and explicit)

```python
import json
import os


def read_json_file(file_path):
    """Read a JSON file from disk and return the parsed object.

    Returns the parsed data on success, or None on failure
    (with the error printed to stderr).

    Args:
        file_path: Path to the JSON file.

    Returns:
        Parsed JSON data (dict, list, etc.) or None if an error occurred.
    """
    try:
        if not os.path.isfile(file_path):
            print(f"Error: File not found: {file_path}")
            return None

        with open(file_path, "r", encoding="utf-8") as f:
            return json.load(f)

    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON in '{file_path}': {e}")
    except PermissionError:
        print(f"Error: Permission denied: {file_path}")
    except OSError as e:
        print(f"Error reading file '{file_path}': {e}")
    except Exception as e:
        print(f"Unexpected error reading '{file_path}': {e}")
    return None
```

**Usage:**

```python
data = read_json_file("config.json")
if data is None:
    print("Failed to load configuration.")
else:
    print(data)
```

**Alternative — raising instead of returning `None`:**

If you'd rather let the caller decide how to handle failures, a cleaner pattern is to re-raise or return an error:

```python
from dataclasses import dataclass

@dataclass
class ReadResult:
    data: object = None
    error: str = None

def read_json(file_path):
    try:
        with open(file_path, "r", encoding="utf-8") as f:
            return ReadResult(data=json.load(f))
    except FileNotFoundError:
        return ReadResult(error=f"File not found: {file_path}")
    except json.JSONDecodeError as e:
        return ReadResult(error=f"Invalid JSON: {e}")
    except OSError as e:
        return ReadResult(error=str(e))
```

This second approach avoids the ambiguity of `None` being valid JSON (`null`), making errors explicit.

```python
def parse_int(value, default=None):
    """Parse an integer from a string, returning default if parsing fails."""
    try:
        return int(str(value).strip())
    except (ValueError, TypeError):
        return default
```

**Example usage:**

```python
print(parse_int("42"))        # 42
print(parse_int("  100  "))   # 100 (whitespace handled)
print(parse_int("-7"))        # -7
print(parse_int("abc"))       # None (default)
print(parse_int("3.5"))      # None (not an int)
print(parse_int("12", 0))     # 12
print(parse_int("oops", 0))   # 0
```

**Notes:**
- `str(value)` makes it safe to pass non-string inputs (e.g., `None`, floats).
- `strip()` handles surrounding whitespace.
- The default is `None` unless you supply your own, so you can easily distinguish failures.

If you want `parse_int("3.5")` to return `3`, you could add a fallback:

```python
def parse_int(value, default=None):
    try:
        return int(str(value).strip())
    except (ValueError, TypeError):
        try:
            return int(float(str(value).strip()))
        except (ValueError, TypeError):
            return default
```

